package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
)

// PostReviewComment takes the array of JSON comments generated by the AI and posts them
// as individual inline threads directly on the Azure DevOps Pull Request files.
func PostReviewComment(org, project, repo, pat string, prID int, comments []ReviewComment) error {
	if len(comments) == 0 {
		fmt.Println("No actionable feedback to post.")
		return nil
	}

	fmt.Printf("💬 Posting %d inline AI comments back to Azure DevOps...\n", len(comments))

	url := fmt.Sprintf("https://dev.azure.com/%s/%s/_apis/git/repositories/%s/pullRequests/%d/threads?api-version=7.1", org, project, repo, prID)

	for i, comment := range comments {
		// Construct the ADO Thread payload
		// A thread can contain multiple comments. We are creating a new thread with a single comment.
		payload := map[string]interface{}{
			"comments": []map[string]interface{}{
				{
					"parentCommentId": 0,
					"content":         comment.Comment,
					"commentType":     1, // 1 = text comment
				},
			},
			"status": 1, // 1 = Active thread
		}

		// Attach to specific file and line if provided
		if comment.File != "" && comment.Line > 0 {
			// Prepend a slash if missing, as ADO sometimes expects absolute repo paths like /src/app.tsx
			filePath := comment.File
			if filePath[0] != '/' {
				filePath = "/" + filePath
			}
			
			payload["threadContext"] = map[string]interface{}{
				"filePath": filePath,
				"rightFileStart": map[string]interface{}{
					"line":   comment.Line,
					"offset": 1,
				},
				"rightFileEnd": map[string]interface{}{
					"line":   comment.Line,
					"offset": 2,
				},
			}
		}

		reqBody, err := json.Marshal(payload)
		if err != nil {
			return fmt.Errorf("failed to marshal comment %d payload: %w", i, err)
		}

		req, err := http.NewRequest("POST", url, bytes.NewBuffer(reqBody))
		if err != nil {
			return fmt.Errorf("failed to create comment request %d: %w", i, err)
		}

		// Authenticate using the PAT
		req.SetBasicAuth("", pat)
		req.Header.Add("Content-Type", "application/json")
		req.Header.Add("Accept", "application/json")

		client := &http.Client{}
		resp, err := client.Do(req)
		if err != nil {
			return fmt.Errorf("failed to execute comment request %d: %w", i, err)
		}

		if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusCreated {
			bodyBytes, _ := io.ReadAll(resp.Body)
			resp.Body.Close()
			return fmt.Errorf("failed to post comment %d, status %d: %s", i, resp.StatusCode, string(bodyBytes))
		}
		resp.Body.Close()
	}

	fmt.Println("✅ Successfully published inline AI Code Reviews to the Pull Request!")
	return nil
}
